//! `cargo xtask codegen [--check]`: generates, from the op registry,
//! `docs/ops/*.md`, `sdk/ts/pixel3d.d.ts` and `sdk/wit/pixel3d.wit`.
//! With `--check`, fails if any generated file is missing or stale.
//!
//! The catalog comes from `pixel3d-cli catalog` (JSON), so this tool stays
//! independent of the pixel3d crates.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde_json::Value;

use crate::{cargo, root};

const HEADER_TS: &str = "// Generated by `cargo xtask codegen` from the op registry. Do not edit.\n";
const HEADER_MD: &str = "<!-- Generated by `cargo xtask codegen` from the op registry. Do not edit. -->\n";

/// `scene.set_transform` as `SceneSetTransform`.
pub fn pascal(id: &str) -> String {
    id.split(['.', '_'])
        .filter(|s| !s.is_empty())
        .map(|s| {
            let mut c = s.chars();
            c.next().map(|f| f.to_ascii_uppercase().to_string() + c.as_str()).unwrap_or_default()
        })
        .collect()
}

fn doc_comment(desc: Option<&str>, indent: &str) -> String {
    match desc.map(str::trim).filter(|d| !d.is_empty()) {
        None => String::new(),
        Some(d) => {
            let d = d.replace("*/", "* /");
            if d.contains('\n') {
                let lines: Vec<String> = d.lines().map(|l| format!("{indent} * {l}").trim_end().to_owned()).collect();
                format!("{indent}/**\n{}\n{indent} */\n", lines.join("\n"))
            } else {
                format!("{indent}/** {d} */\n")
            }
        }
    }
}

fn is_ident(s: &str) -> bool {
    s.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_') && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// TypeScript type of a JSON Schema (the subset schemars emits).
pub fn ts_type(schema: &Value, indent: &str) -> String {
    match schema {
        Value::Bool(true) => return "unknown".into(),
        Value::Bool(false) => return "never".into(),
        Value::Object(_) => {}
        _ => return "unknown".into(),
    }
    if let Some(r) = schema.get("$ref").and_then(Value::as_str) {
        return r.rsplit('/').next().unwrap_or("unknown").to_owned();
    }
    if let Some(c) = schema.get("const") {
        return c.to_string();
    }
    if let Some(e) = schema.get("enum").and_then(Value::as_array) {
        return e.iter().map(Value::to_string).collect::<Vec<_>>().join(" | ");
    }
    for key in ["oneOf", "anyOf"] {
        if let Some(list) = schema.get(key).and_then(Value::as_array) {
            let mut parts: Vec<String> = Vec::new();
            for s in list {
                let t = ts_type(s, indent);
                if !parts.contains(&t) {
                    parts.push(t);
                }
            }
            return parts.join(" | ");
        }
    }
    let types: Vec<&str> = match schema.get("type") {
        Some(Value::String(t)) => vec![t.as_str()],
        Some(Value::Array(ts)) => ts.iter().filter_map(Value::as_str).collect(),
        _ => return "unknown".into(),
    };
    let parts: Vec<String> = types.iter().map(|t| single(schema, t, indent)).collect();
    parts.join(" | ")
}

fn single(schema: &Value, ty: &str, indent: &str) -> String {
    match ty {
        "string" => "string".into(),
        "number" | "integer" => "number".into(),
        "boolean" => "boolean".into(),
        "null" => "null".into(),
        "array" => {
            let item = schema.get("items").map_or_else(|| "unknown".to_owned(), |i| ts_type(i, indent));
            let item = if item.contains(" | ") { format!("({item})") } else { item };
            match (schema.get("minItems").and_then(Value::as_u64), schema.get("maxItems").and_then(Value::as_u64)) {
                (Some(a), Some(b)) if a == b && a <= 8 => format!("[{}]", vec![item; a as usize].join(", ")),
                _ => format!("{item}[]"),
            }
        }
        "object" => object_type(schema, indent),
        _ => "unknown".into(),
    }
}

fn object_type(schema: &Value, indent: &str) -> String {
    let props = schema.get("properties").and_then(Value::as_object);
    match props {
        Some(props) if !props.is_empty() => {
            let required: Vec<&str> =
                schema.get("required").and_then(Value::as_array).map(|r| r.iter().filter_map(Value::as_str).collect()).unwrap_or_default();
            let inner = format!("{indent}  ");
            let mut out = String::from("{\n");
            for (name, p) in props {
                out.push_str(&doc_comment(p.get("description").and_then(Value::as_str), &inner));
                let key = if is_ident(name) { name.clone() } else { format!("{name:?}") };
                let opt = if required.contains(&name.as_str()) { "" } else { "?" };
                out.push_str(&format!("{inner}{key}{opt}: {};\n", ts_type(p, &inner)));
            }
            out.push_str(indent);
            out.push('}');
            out
        }
        _ => match schema.get("additionalProperties") {
            Some(Value::Bool(false)) => "Record<string, never>".into(),
            Some(v @ Value::Object(_)) => format!("Record<string, {}>", ts_type(v, indent)),
            _ => "Record<string, unknown>".into(),
        },
    }
}

/// Generated files, keyed by path relative to the workspace root.
pub fn generate(catalog: &Value) -> Result<BTreeMap<PathBuf, String>, String> {
    let ops = catalog["ops"].as_array().ok_or("catalog has no ops")?;
    let version = catalog["app_version"].as_str().unwrap_or("0.0.0");
    let mut files = BTreeMap::new();
    files.insert(PathBuf::from("sdk/ts/pixel3d.d.ts"), typescript(ops)?);
    files.insert(PathBuf::from("sdk/wit/pixel3d.wit"), wit(version));
    files.insert(PathBuf::from("docs/ops/README.md"), ops_index(ops));
    for op in ops {
        let id = op["id"].as_str().ok_or("op without id")?;
        files.insert(PathBuf::from(format!("docs/ops/{id}.md")), op_page(op));
    }
    Ok(files)
}

fn typescript(ops: &[Value]) -> Result<String, String> {
    // Shared definitions: identical schemas under one name are emitted once;
    // a name reused with another schema is a generator error to fix at the source.
    let mut defs: BTreeMap<String, Value> = BTreeMap::new();
    for op in ops {
        if let Some(d) = op["params"].get("$defs").and_then(Value::as_object) {
            for (name, s) in d {
                match defs.get(name) {
                    Some(prev) if prev != s => return Err(format!("type `{name}` has two different schemas (seen again in {})", op["id"])),
                    _ => {
                        defs.insert(name.clone(), s.clone());
                    }
                }
            }
        }
    }
    let mut out = String::from(HEADER_TS);
    out.push_str("// Parameter types of every pixel3d op, for scripts, addons and agents.\n\n");
    for (name, s) in &defs {
        out.push_str(&doc_comment(s.get("description").and_then(Value::as_str), ""));
        out.push_str(&format!("export type {name} = {};\n\n", ts_type(s, "")));
    }
    for op in ops {
        let id = op["id"].as_str().unwrap_or_default();
        out.push_str(&doc_comment(Some(&format!("`{id}`: {}", op["summary"].as_str().unwrap_or_default())), ""));
        out.push_str(&format!("export type {}Params = {};\n\n", pascal(id), ts_type(&op["params"], "")));
    }
    out.push_str("/** Parameters of each op, by op id. */\nexport interface OpParams {\n");
    for op in ops {
        let id = op["id"].as_str().unwrap_or_default();
        out.push_str(&format!("  {id:?}: {}Params;\n", pascal(id)));
    }
    out.push_str("}\n\n/** Every op id. */\nexport type OpId = keyof OpParams;\n");
    Ok(out)
}

fn wit(version: &str) -> String {
    format!(
        "// Generated by `cargo xtask codegen`. Do not edit.\n\
// Arguments are JSON strings so the interface stays stable while ops evolve;\n\
// bulk geometry uses typed lists. Op schemas: sdk/ts/pixel3d.d.ts, docs/ops.\n\n\
package pixel3d:api@{version};\n\n\
interface types {{\n\
    type object-id = string;\n\
    record vec3 {{ x: f32, y: f32, z: f32 }}\n\
    record op-error {{ code: string, message: string, path: option<string>, hint: option<string> }}\n\
    record mesh-buffers {{\n\
        /// xyz interleaved\n\
        positions: list<f32>,\n\
        /// corners per face\n\
        face-sizes: list<u32>,\n\
        /// vertex index per corner\n\
        corner-verts: list<u32>,\n\
        /// uv per corner\n\
        corner-uv0: option<list<f32>>,\n\
        face-material: option<list<u16>>,\n\
        /// face groups\n\
        groups: list<tuple<string, list<u32>>>,\n\
    }}\n\
    enum level {{ trace, debug, info, warn, error }}\n\
}}\n\n\
interface host {{\n\
    use types.{{object-id, op-error, mesh-buffers, level}};\n\
    run-op: func(op: string, args-json: string) -> result<string, op-error>;\n\
    query: func(target: object-id, selector-json: string) -> result<list<u32>, op-error>;\n\
    describe: func(target: object-id) -> result<string, op-error>;\n\
    read-mesh: func(target: object-id) -> result<mesh-buffers, op-error>;\n\
    write-mesh: func(target: object-id, mesh: mesh-buffers) -> result<_, op-error>;\n\
    log: func(lvl: level, msg: string);\n\
    /// false means cancelled\n\
    progress: func(fraction: f32) -> bool;\n\
}}\n\n\
world addon {{\n\
    import host;\n\
    /// ops with JSON Schemas, ui hints\n\
    export manifest: func() -> string;\n\
    export run: func(op: string, args-json: string) -> result<string, types.op-error>;\n\
}}\n"
    )
}

fn ops_index(ops: &[Value]) -> String {
    let mut out = String::from(HEADER_MD);
    out.push_str("# Ops\n\nEvery operation in pixel3d. The GUI, CLI, MCP server, scripts, addons and the node graph all call these.\n");
    let mut by_cat: BTreeMap<&str, Vec<&Value>> = BTreeMap::new();
    let mut order: Vec<&str> = Vec::new();
    for op in ops {
        let c = op["category"].as_str().unwrap_or("other");
        if !order.contains(&c) {
            order.push(c);
        }
        by_cat.entry(c).or_default().push(op);
    }
    for c in order {
        out.push_str(&format!("\n## {c}\n\n| Op | Summary |\n|---|---|\n"));
        for op in &by_cat[c] {
            let id = op["id"].as_str().unwrap_or_default();
            out.push_str(&format!("| [`{id}`]({id}.md) | {} |\n", op["summary"].as_str().unwrap_or_default()));
        }
    }
    out
}

fn op_page(op: &Value) -> String {
    let id = op["id"].as_str().unwrap_or_default();
    let s = |k: &str| op[k].as_str().unwrap_or_default().to_owned();
    let list = |k: &str| op[k].as_array().map(|a| a.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(", ")).unwrap_or_default();
    let mut out = String::from(HEADER_MD);
    out.push_str(&format!("# `{id}`: {}\n\n{}\n\n", s("label"), s("summary")));
    out.push_str(&format!("- Category: {}\n- Version: {}\n- Complexity: {}\n", s("category"), op["version"], s("complexity")));
    let flags = list("flags");
    if !flags.is_empty() {
        out.push_str(&format!("- Flags: {flags}\n"));
    }
    let aliases = list("aliases");
    if !aliases.is_empty() {
        out.push_str(&format!("- Also known as: {aliases}\n"));
    }
    out.push_str(&format!("\n{}\n\n## Parameters\n\n", s("docs").trim()));
    let params = &op["params"];
    let required: Vec<&str> =
        params.get("required").and_then(Value::as_array).map(|r| r.iter().filter_map(Value::as_str).collect()).unwrap_or_default();
    match params.get("properties").and_then(Value::as_object) {
        Some(props) if !props.is_empty() => {
            out.push_str("| Name | Type | Default | Description |\n|---|---|---|---|\n");
            for (name, p) in props {
                let ty = ts_type(p, "").replace('\n', " ").split_whitespace().collect::<Vec<_>>().join(" ").replace('|', "\\|");
                let default = if required.contains(&name.as_str()) {
                    "required".to_owned()
                } else {
                    op["defaults"].get(name).map_or_else(|| "-".to_owned(), |d| format!("`{d}`"))
                };
                let desc = p.get("description").and_then(Value::as_str).unwrap_or("").replace('\n', " ").replace('|', "\\|");
                out.push_str(&format!("| `{name}` | `{ty}` | {default} | {desc} |\n"));
            }
        }
        _ => out.push_str("None.\n"),
    }
    if let Some(examples) = op["examples"].as_array().filter(|e| !e.is_empty()) {
        out.push_str("\n## Examples\n");
        for ex in examples {
            out.push_str(&format!("\n```json\n{}\n```\n\nResult: `{}`\n", ex["args"], ex["result"].as_str().unwrap_or_default()));
        }
    }
    out
}

/// Runs `pixel3d-cli catalog` and parses its JSON.
fn load_catalog() -> Result<Value, String> {
    let out = cargo().args(["run", "--quiet", "-p", "pixel3d-cli", "--", "catalog"]).output().map_err(|e| format!("pixel3d-cli catalog: {e}"))?;
    if !out.status.success() {
        return Err(format!("pixel3d-cli catalog failed:\n{}", String::from_utf8_lossy(&out.stderr)));
    }
    serde_json::from_slice(&out.stdout).map_err(|e| format!("catalog JSON: {e}"))
}

/// Generated docs pages on disk that the catalog no longer produces.
fn stale_pages(root: &Path, files: &BTreeMap<PathBuf, String>) -> Vec<PathBuf> {
    let dir = root.join("docs/ops");
    let mut out: Vec<PathBuf> = std::fs::read_dir(&dir)
        .into_iter()
        .flatten()
        .filter_map(Result::ok)
        .map(|e| PathBuf::from("docs/ops").join(e.file_name()))
        .filter(|p| p.extension().is_some_and(|x| x == "md") && !files.contains_key(p))
        .collect();
    out.sort();
    out
}

pub fn run(args: &[&str]) -> Result<(), String> {
    let check = args.contains(&"--check");
    let root = root();
    let files = generate(&load_catalog()?)?;
    let stale = stale_pages(&root, &files);
    if check {
        let mut problems: Vec<String> = files
            .iter()
            .filter(|(p, content)| std::fs::read_to_string(root.join(p)).ok().as_deref() != Some(content.as_str()))
            .map(|(p, _)| format!("{} is missing or out of date", p.display()))
            .collect();
        problems.extend(stale.iter().map(|p| format!("{} belongs to no op", p.display())));
        return if problems.is_empty() {
            println!("codegen: OK, {} generated files are up to date.", files.len());
            Ok(())
        } else {
            Err(format!("generated files are stale; run `cargo xtask codegen`:\n  {}", problems.join("\n  ")))
        };
    }
    let mut written = 0;
    for (p, content) in &files {
        let path = root.join(p);
        if std::fs::read_to_string(&path).ok().as_deref() == Some(content.as_str()) {
            continue;
        }
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        }
        std::fs::write(&path, content).map_err(|e| format!("{}: {e}", path.display()))?;
        written += 1;
    }
    for p in &stale {
        std::fs::remove_file(root.join(p)).map_err(|e| format!("{}: {e}", p.display()))?;
    }
    println!("codegen: {} files, {written} written, {} removed.", files.len(), stale.len());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn names() {
        assert_eq!(pascal("scene.set_transform"), "SceneSetTransform");
        assert_eq!(pascal("prim.box"), "PrimBox");
    }

    #[test]
    fn schema_to_typescript() {
        assert_eq!(ts_type(&json!({ "type": ["string", "null"] }), ""), "string | null");
        assert_eq!(
            ts_type(&json!({ "type": "array", "items": { "$ref": "#/$defs/Length" }, "minItems": 3, "maxItems": 3 }), ""),
            "[Length, Length, Length]"
        );
        assert_eq!(ts_type(&json!({ "type": "array", "items": { "type": "integer" } }), ""), "number[]");
        assert_eq!(ts_type(&json!({ "oneOf": [{ "const": "a", "type": "string" }, { "const": "b", "type": "string" }] }), ""), "\"a\" | \"b\"");
        assert_eq!(ts_type(&json!({ "anyOf": [{ "$ref": "#/$defs/X" }, { "type": "null" }] }), ""), "X | null");
        assert_eq!(ts_type(&json!({ "type": "object", "additionalProperties": true }), ""), "Record<string, unknown>");
        assert_eq!(ts_type(&json!(true), ""), "unknown");
        let obj = json!({ "type": "object", "properties": { "a": { "type": "number", "description": "An a." }, "b-c": { "type": "string" } }, "required": ["a"] });
        assert_eq!(ts_type(&obj, ""), "{\n  /** An a. */\n  a: number;\n  \"b-c\"?: string;\n}");
        let union_items = json!({ "type": "array", "items": { "anyOf": [{ "type": "number" }, { "type": "string" }] } });
        assert_eq!(ts_type(&union_items, ""), "(number | string)[]");
    }

    #[test]
    fn generates_all_files_and_rejects_conflicting_types() {
        let op = |id: &str, def: Value| {
            json!({ "id": id, "label": "L", "category": "prim", "summary": "S.", "docs": "D", "aliases": [], "complexity": "O(1)",
                    "flags": ["undoable"], "version": 1, "examples": [{ "args": { "a": 1 }, "result": "ok" }],
                    "params": { "type": "object", "properties": { "a": { "$ref": "#/$defs/T" } }, "$defs": { "T": def } }, "defaults": { "a": 1 } })
        };
        let cat = json!({ "app_version": "1.2.3", "ops": [op("prim.a", json!({ "type": "number" })), op("prim.b", json!({ "type": "number" }))] });
        let files = generate(&cat).unwrap();
        let keys: Vec<String> = files.keys().map(|p| p.display().to_string()).collect();
        assert_eq!(keys, vec!["docs/ops/README.md", "docs/ops/prim.a.md", "docs/ops/prim.b.md", "sdk/ts/pixel3d.d.ts", "sdk/wit/pixel3d.wit"]);
        let ts = &files[&PathBuf::from("sdk/ts/pixel3d.d.ts")];
        assert_eq!(ts.matches("export type T =").count(), 1, "shared definitions are emitted once");
        assert!(ts.contains("\"prim.a\": PrimAParams;"));
        assert!(files[&PathBuf::from("sdk/wit/pixel3d.wit")].contains("package pixel3d:api@1.2.3;"));
        let bad = json!({ "app_version": "1", "ops": [op("prim.a", json!({ "type": "number" })), op("prim.b", json!({ "type": "string" }))] });
        assert!(generate(&bad).is_err());
    }
}
